# 2) Light sweep: every kernel of a short decode range, metrics only (production config: CUDA graphs).
#    Application replay: the whole program runs once per metric pass. Kernel replay would save and restore
#    ~57 GB of device memory through host RAM for each of the ~8,000 kernels (days instead of ~30 min).
GMU=0.72 run sweep_b1 --target-processes all --profile-from-start off --graph-profiling node \
  --replay-mode application --app-replay-mode relaxed \
  --nvtx --nvtx-include "prefill_decode8_b1/" --metrics gpu__time_duration.sum,dram__bytes_read.sum,dram__bytes_write.sum,dram__throughput.avg.pct_of_peak_sustained_elapsed,sm__throughput.avg.pct_of_peak_sustained_elapsed,launch__grid_size --clock-control none \
